 const LAST_SEEN_SAVE_INTERVAL_SECS: u64 = 300;

+/// The text the pairing QR carries: the page's address with the code,
+/// the host's key and its id in the fragment, which a browser never
+/// sends, so the code stays out of the first request and every log.
+#[must_use]
+pub fn invite_url(
+    identity: &Identity,
+    window: &PairingWindow,
+    address: IpAddr,
+    port: u16,
+) -> String {
+    let host = match address {
+        IpAddr::V4(ip) => ip.to_string(),
+        IpAddr::V6(ip) => format!("[{ip}]"),
+    };
+    format!(
+        "https://{host}:{port}/#code={}&key={}&id={}",
+        window.code, identity.spki_sha256, identity.server_id
+    )
+}
+
+/// The cookie a browser holds its token in for one host. The id is in
+/// the name because cookies ignore ports, so two instances on one
+/// address would otherwise overwrite each other's credential.
+#[must_use]
+pub fn cookie_name(server_id: Uuid) -> String {
+    format!("__Host-sb-{server_id}")
+}
+
+/// The value of the cookie `name` in a `Cookie` header, matched by exact
+/// name; every other cookie is ignored.
+#[must_use]
+pub fn cookie_value<'a>(header: &'a str, name: &str) -> Option<&'a str> {
+    header
+        .split(';')
+        .filter_map(|pair| pair.trim().split_once('='))
+        .find(|(n, _)| *n == name)
+        .map(|(_, v)| v)
+        .filter(|v| !v.is_empty())
+}
